cat package.json; sed -n '370,430p' index.js; mkdir -p .suffice-checks; cat > .suffice-checks/probe.mjs <<'EOF'
import assert from 'node:assert/strict';
import Emittery from '../index.js';
class YieldingEmittery extends Emittery {
  async emit(...args) {
    await new Promise(resolve => setImmediate(resolve));
    return super.emit(...args);
  }
}
const emitter = new YieldingEmittery();
let calls = 0;
emitter.on(Emittery.listenerAdded, () => { calls++; });
emitter.on('value', () => {});
await new Promise(resolve => setImmediate(resolve));
assert.equal(calls, 2, 'listenerAdded meta event should work with async emit override');
EOF
