import http from 'node:http';
import fetch from '../src/index.js';
const server = http.createServer((request, response) => {
 response.writeHead(302, {Location: '//super:invalid:url%/'}).end();
});
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
try {
 let caught = false;
 try { await fetch(`http://127.0.0.1:${server.address().port}/`); } catch (error) {
  caught = true;
  if (!(error instanceof TypeError) && error.type !== 'invalid-redirect') throw error;
 }
 if (!caught) throw new Error('expected invalid redirect to reject');
 console.log('invalid redirect rejected');
} finally { server.close(); }
EOF
cat > .suffice-checks/preserve.mjs <<'EOF'
import http from 'node:http';
import fetch from '../src/index.js';
const server = http.createServer((request, response) => {
 response.writeHead(302, {Location: '/ok'}).end();
});
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
try {
 const response = await fetch(`http://127.0.0.1:${server.address().port}/`, {redirect: 'manual'});
 if (response.headers.get('location') !== `http://127.0.0.1:${server.address().port}/ok`) throw new Error('manual redirect location not resolved');
 console.log('manual redirect preserved');
} finally { server.close(); }
EOF
