mkdir -p .suffice-checks && cat > .suffice-checks/probe.mjs <<'EOF'
import http from 'node:http';
import fetch from '../src/index.js';

const server = http.createServer((request, response) => {
	response.setHeader('content-encoding', 'deflate');
	response.end();
});
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
try {
	const result = await Promise.race([
		fetch(`http://127.0.0.1:${server.address().port}`).then(response => response.text()),
		new Promise((resolve, reject) => setTimeout(() => reject(new Error('empty deflate response did not resolve')), 500))
	]);
	if (result !== '') throw new Error(`Expected empty response, received ${JSON.stringify(result)}`);
	console.log('Empty deflate response resolved');
} finally {
	server.close();
}
EOF
