import PQueue from '../source/index.ts';
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));
const queue = new PQueue({intervalCap: 2, interval: 250});
await queue.add(() => {});
await delay(150);
await queue.add(() => {});
await queue.onIdle();
await delay(125);
const started = Date.now();
await queue.add(() => {});
const waited = Date.now() - started;
console.log(`Fresh-window task waited ${waited}ms`);
if (waited > 80) throw new Error(`Expected immediate fresh-window task; waited ${waited}ms`);
EOF
