const queue = new PQueue({intervalCap: 2, interval: 500});
const result = [];
await Promise.all([queue.add(() => result.push('first')), queue.add(() => result.push('second'))]);
if (result.length !== 2) throw new Error('Both available interval slots should execute');
console.log('Preserved: both tasks execute within the two-slot window');
