mkdir -p .suffice-checks && cat > .suffice-checks/probe.mjs <<'EOF'
import assert from 'node:assert/strict';
import PQueue from '../source/index.ts';

const queue = new PQueue({concurrency: 3, autoStart: false});
for (let i = 0; i < 5; i++) {
  queue.add(() => new Promise(resolve => setTimeout(resolve, 100)));
}
let settled = false;
const waiting = queue.onSizeLessThan(3).then(() => { settled = true; });
queue.start();
await new Promise(resolve => setImmediate(resolve));
assert.equal(queue.size, 2);
assert.equal(settled, true, 'onSizeLessThan should resolve when dequeueing crosses its limit');
await waiting;
await queue.onIdle();
EOF
